class Employee {
  + Name : string
  + Ssn : int
}

class CreativeEmployee extends Employee {
  + IsOscarWinner : boolean
}

class Director extends CreativeEmployee {
  + AssistantName : string
}

class Actor extends CreativeEmployee {
  + Education : string
}

class Technician extends Employee {
  + FieldOfActivity : string
}

class Location {
  + Name : string
}

class Film {
  + Title : string
  + ReleaseYear : int
}

class Genre {
  + Type : string
}

class Screenwriter {
  + Name : string
  + MostSuccessfulFilm : string
}

class Screenplay {
  + Title : string
  + Version : string
  + Date : date
  + NumberOfScenes : int
  + Plot : string
}

class Novel {
  + Title : string
  + Author : string
}

class Concept {
}

class Role {
}

Film "*" -- "*" Location : is shot at
Film "*" -- "1" Genre : is assigned to
Film "1" -- "1" Screenplay : is based on
Film "1" -- "*" Actor : features
Actor "1" -- "1" Role : plays
Role "1" -- "1" Screenplay : reads
Screenplay "1" -- "1" Screenwriter : is written by
Screenplay "0..*" -- "0..1" Novel : is based on
Screenplay "0..*" -- "0..1" Concept : is based on
Screenwriter "1" -- "*" Screenplay : creates

@enduml

